// The cleaner can live side by side with the manual calling of `destroy`. In the order of responsiveness, uniffi objects
// with Rust peers are reclaimed:
//
// 1. By calling the `destroy` method of the object, which calls `rustObject.free()`. If that doesn't happen:
// 2. When the object becomes unreachable, AND the Cleaner thread gets to call `rustObject.free()`. If the thread is starved then:
// 3. The memory is reclaimed when the process terminates.
//
// [1] https://stackoverflow.com/questions/24376768/can-java-finalize-an-object-when-it-is-still-in-scope/24380219
//


/**
 * One terminal session over the PTY lane (T37/T42): the pinned SSH
 * connection plus a phone-sized PTY running the host's shell in the
 * workspace's folder — never an agent. Output is drained off the UI thread
 * by [`TerminalSession::read`] and delivered the moment it arrives, never
 * batched behind a full buffer.
 */
public interface TerminalSessionInterface {
    
    /**
     * Orderly shutdown: close the channel and join the pump. Idempotent.
     * Named `close_session` because the generated binding already
     * implements `AutoCloseable.close`.
     */
    fun `closeSession`()
    
    /**
     * The current column count.
     */
    fun `cols`(): kotlin.UInt
    
    /**
     * The shell's exit status, once the host sent one.
     */
    fun `exitStatus`(): kotlin.UInt?
    
    /**
     * True once the stream reached its end, however it ended.
     */
    fun `isClosed`(): kotlin.Boolean
    
    /**
     * The reason the pump ended, once it has.
     */
    fun `lastError`(): kotlin.String?
    
    /**
     * The next bytes from the host, delivered the moment they arrive.
     * Up to `max_bytes`; an empty answer means none are pending, never an
     * error — the UI polls this and redraws as soon as bytes exist.
     */
    fun `read`(`maxBytes`: kotlin.UInt): kotlin.ByteArray
    
    /**
     * Reshape the terminal without reopening the channel.
     */
    fun `resize`(`cols`: kotlin.UInt, `rows`: kotlin.UInt)
    
    /**
     * The current row count.
     */
    fun `rows`(): kotlin.UInt
    
    /**
     * Write keystrokes or paste to the host in one piece, verbatim.
     */
    fun `write`(`bytes`: kotlin.ByteArray)
    
    companion object
}

/**
 * One terminal session over the PTY lane (T37/T42): the pinned SSH
 * connection plus a phone-sized PTY running the host's shell in the
 * workspace's folder — never an agent. Output is drained off the UI thread
 * by [`TerminalSession::read`] and delivered the moment it arrives, never
 * batched behind a full buffer.
 */
open class TerminalSession: Disposable, AutoCloseable, TerminalSessionInterface
{

    @Suppress("UNUSED_PARAMETER")
    /**
     * @suppress
     */
    constructor(withHandle: UniffiWithHandle, handle: Long) {
        this.handle = handle
        this.cleanable = UniffiLib.CLEANER.register(this, UniffiCleanAction(handle))
    }

    /**
     * @suppress
     *
     * This constructor can be used to instantiate a fake object. Only used for tests. Any
     * attempt to actually use an object constructed this way will fail as there is no
     * connected Rust object.
     */
    @Suppress("UNUSED_PARAMETER")
    constructor(noHandle: NoHandle) {
        this.handle = 0
        this.cleanable = null
    }

    protected val handle: Long
    protected val cleanable: UniffiCleaner.Cleanable?

    private val wasDestroyed = AtomicBoolean(false)
    private val callCounter = AtomicLong(1)

    /**
     * Whether the current object has been destroyed and its reference is gone in the Rust side.
     */
    val uniffiIsDestroyed: Boolean get() = wasDestroyed.get()

    override fun destroy() {
        // Only allow a single call to this method.
        // TODO: maybe we should log a warning if called more than once?
        if (this.wasDestroyed.compareAndSet(false, true)) {
            // This decrement always matches the initial count of 1 given at creation time.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    @Synchronized
    override fun close() {
        this.destroy()
    }

    internal inline fun <R> callWithHandle(block: (handle: Long) -> R): R {
        // Check and increment the call counter, to keep the object alive.
        // This needs a compare-and-set retry loop in case of concurrent updates.
        do {
            val c = this.callCounter.get()
            if (c == 0L) {
                throw IllegalStateException("${this.javaClass.simpleName} object has already been destroyed")
            }
            if (c == Long.MAX_VALUE) {
                throw IllegalStateException("${this.javaClass.simpleName} call counter would overflow")
            }
        } while (! this.callCounter.compareAndSet(c, c + 1L))
        // Now we can safely do the method call without the handle being freed concurrently.
        try {
            return block(this.uniffiCloneHandle())
        } finally {
            // This decrement always matches the increment we performed above.
            if (this.callCounter.decrementAndGet() == 0L) {
                cleanable?.clean()
            }
        }
    }

    // Use a static inner class instead of a closure so as not to accidentally
    // capture `this` as part of the cleanable's action.
    private class UniffiCleanAction(private val handle: Long) : Runnable {
        override fun run() {
            if (handle == 0.toLong()) {
                // Fake object created with `NoHandle`, don't try to free.
                return;
            }
            uniffiRustCall { status ->
                UniffiLib.uniffi_gentlecompanion_core_fn_free_terminalsession(handle, status)
            }
        }
    }

    /**
     * @suppress
     */
    fun uniffiCloneHandle(): Long {
        if (handle == 0.toLong()) {
            throw InternalException("uniffiCloneHandle() called on NoHandle object");
        }
        return uniffiRustCall() { status ->
            UniffiLib.uniffi_gentlecompanion_core_fn_clone_terminalsession(handle, status)
        }
    }

    
    /**
     * Orderly shutdown: close the channel and join the pump. Idempotent.
     * Named `close_session` because the generated binding already
     * implements `AutoCloseable.close`.
     */override fun `closeSession`()
        = 
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_close_session(
        it,
        _status)
}
    }
    
    

    
    /**
     * The current column count.
     */override fun `cols`(): kotlin.UInt {
            return FfiConverterUInt.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_cols(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The shell's exit status, once the host sent one.
     */override fun `exitStatus`(): kotlin.UInt? {
            return FfiConverterOptionalUInt.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_exit_status(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * True once the stream reached its end, however it ended.
     */override fun `isClosed`(): kotlin.Boolean {
            return FfiConverterBoolean.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_is_closed(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The reason the pump ended, once it has.
     */override fun `lastError`(): kotlin.String? {
            return FfiConverterOptionalString.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_last_error(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * The next bytes from the host, delivered the moment they arrive.
     * Up to `max_bytes`; an empty answer means none are pending, never an
     * error — the UI polls this and redraws as soon as bytes exist.
     */override fun `read`(`maxBytes`: kotlin.UInt): kotlin.ByteArray {
            return FfiConverterByteArray.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_read(
        it,
        
        FfiConverterUInt.lower(`maxBytes`),_status)
}
    }
    )
    }
    

    
    /**
     * Reshape the terminal without reopening the channel.
     */
    @Throws(CompanionException::class)override fun `resize`(`cols`: kotlin.UInt, `rows`: kotlin.UInt)
        = 
    callWithHandle {
    uniffiRustCallWithError(CompanionException) { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_resize(
        it,
        
        FfiConverterUInt.lower(`cols`),
        FfiConverterUInt.lower(`rows`),_status)
}
    }
    
    

    
    /**
     * The current row count.
     */override fun `rows`(): kotlin.UInt {
            return FfiConverterUInt.lift(
    callWithHandle {
    uniffiRustCall() { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_rows(
        it,
        _status)
}
    }
    )
    }
    

    
    /**
     * Write keystrokes or paste to the host in one piece, verbatim.
     */
    @Throws(CompanionException::class)override fun `write`(`bytes`: kotlin.ByteArray)
        = 
    callWithHandle {
    uniffiRustCallWithError(CompanionException) { _status ->
    UniffiLib.uniffi_gentlecompanion_core_fn_method_terminalsession_write(
        it,
        
        FfiConverterByteArray.lower(`bytes`),_status)
}
    }
    
    

    

    


    
    
    /**
     * @suppress
     */
    companion object
    
}


/**
 * @suppress
 */
public object FfiConverterTypeTerminalSession: FfiConverter<TerminalSession, Long> {
    override fun lower(value: TerminalSession): Long {
        return value.uniffiCloneHandle()
    }

    override fun lift(value: Long): TerminalSession {
        return TerminalSession(UniffiWithHandle, value)
    }

    override fun read(buf: ByteBuffer): TerminalSession {
        return lift(buf.getLong())
    }

    override fun allocationSize(value: TerminalSession) = 8UL

    override fun write(value: TerminalSession, buf: ByteBuffer) {
        buf.putLong(lower(value))
    }
}



