/**
 * Errors the UI matches on. Pinning failures keep their typed shape; the
 * transport detail collapses into a message.
 */
sealed class CompanionException: kotlin.Exception() {
    
    class HostKeyUnknown(
        
        val `host`: kotlin.String, 
        
        val `port`: kotlin.UShort, 
        
        val `fingerprint`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "host=${ `host` }, port=${ `port` }, fingerprint=${ `fingerprint` }"
    }
    
    class HostKeyMismatch(
        
        val `host`: kotlin.String, 
        
        val `port`: kotlin.UShort, 
        
        val `pinned`: kotlin.String, 
        
        val `presented`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "host=${ `host` }, port=${ `port` }, pinned=${ `pinned` }, presented=${ `presented` }"
    }
    
    class InvalidKeyBlob(
        ) : CompanionException() {
        override val message
            get() = ""
    }
    
    class Timeout(
        
        val `detail`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    class Transport(
        
        val `detail`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The daemon answered a request with an error object.
     */
    class RequestRefused(
        
        val `code`: kotlin.String, 
        
        val `detail`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "code=${ `code` }, detail=${ `detail` }"
    }
    
    /**
     * The daemon's advertised method list has no such method.
     */
    class UnsupportedMethod(
        
        val `method`: kotlin.String, 
        
        val `detail`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "method=${ `method` }, detail=${ `detail` }"
    }
    
    /**
     * The file is over the upload size limit; refused before any byte moved.
     */
    class UploadTooLarge(
        
        val `sizeBytes`: kotlin.ULong, 
        
        val `maxBytes`: kotlin.ULong
        ) : CompanionException() {
        override val message
            get() = "sizeBytes=${ `sizeBytes` }, maxBytes=${ `maxBytes` }"
    }
    
    /**
     * The file name has no usable form once sanitised.
     */
    class UploadEmptyName(
        ) : CompanionException() {
        override val message
            get() = ""
    }
    
    /**
     * The resume path is not a regular file on the host (T17b).
     */
    class RpcSessionNotAFile(
        
        val `path`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "path=${ `path` }"
    }
    
    /**
     * The directory a fresh session should start in does not exist on the
     * host, or is not a directory (S24-5).
     */
    class RpcStartNotADirectory(
        
        val `path`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "path=${ `path` }"
    }
    
    /**
     * A live lease held by another device — refused, never opened (S18).
     */
    class RpcSessionLeasedElsewhere(
        
        val `detail`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The host could not spawn `gentle-shell --mode rpc`.
     */
    class RpcSpawnRefused(
        
        val `detail`: kotlin.String
        ) : CompanionException() {
        override val message
            get() = "detail=${ `detail` }"
    }
    
    /**
     * The child did not speak the expected protocol, or reported a
     * different session id than the list showed.
     */
    class RpcProtocolGarbage(
        
