/**
 * Either the host-key question or a live connection — the two things a
 * connect can be.
 */
sealed class ConnectOutcome: Disposable  {
    
    data class Challenge(
        val v1: com.gentlemanprogramming.gentlemobile.core.HostKeyChallenge) : ConnectOutcome()
        
    {
        

        companion object
    }
    
    data class Connected(
        val v1: com.gentlemanprogramming.gentlemobile.core.CompanionConnection) : ConnectOutcome()
        
    {
        

        companion object
    }
    

    
    @Suppress("UNNECESSARY_SAFE_CALL") // codegen is much simpler if we unconditionally emit safe calls here
    override fun destroy() {
        when(this) {
            is ConnectOutcome.Challenge -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
            is ConnectOutcome.Connected -> {
                
    Disposable.destroy(
        this.v1
    )
                
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }
    

    
    


    companion object
}

