                )
            2 -> ConnectOutcome.Connected(
                FfiConverterTypeCompanionConnection.read(buf),
                )
            else -> throw RuntimeException("invalid enum value, something is very wrong!!")
        }
    }

    override fun allocationSize(value: ConnectOutcome): ULong = when(value) {
