    UniffiLib.uniffi_gentlecompanion_core_fn_func_accept_host_key(
    
        
        FfiConverterString.lower(`knownHostsPath`),
        FfiConverterString.lower(`host`),
        FfiConverterUShort.lower(`port`),
        FfiConverterString.lower(`keyBlob`),_status)
}
    
    

